      "age": "«34 ans » - 34 ans",
      "origine": "Américaine",
      "statut": "Gouvernement -corporatistes",
      "statut_verite": "Avocate de Clara ARELLANO-FELIX",
      "relations": [
        "Clara ARELLANO-FELIX"
      ],
      "source_group": "Rocréens",
